//! The "My tickets" window: the tickets this app created in the last week (see `history`), one
//! opened in an editor where its title and description can be edited by hand or regenerated by
//! the LLM from the material it was created from, then saved to Jira. Nothing is written to Jira
//! before Save.

use std::sync::Arc;
use std::sync::mpsc::{Receiver, TryRecvError, channel};

use eframe::egui;

use crate::config::{Config, JiraCredentials};
use crate::drafting::{self, CurrentTicket, Stage, WorkItem};
use crate::history::{History, KEEP_DAYS, TicketRecord};
use crate::jira::{Issue, IssueDetails, Jira, project_of};
use crate::llm::{self, Llm, MAX_TITLE_CHARS, TicketDraft};
use crate::ui_tickets::EVIDENCE_TEXT_SIZE;

/// The items Regenerate sends: the stored sources, without their diffs when `send_code` is off.
pub fn regen_items(sources: &[WorkItem], send_code: bool) -> Vec<WorkItem> {
    sources.iter().map(|w| WorkItem { line: w.line.clone(), change: w.change.clone().filter(|_| send_code) }).collect()
}

/// Saves the given fields of `loaded.key`, unless the issue changed in Jira since it was loaded
/// (someone else's edit would be overwritten unseen); returns Jira's state after the save.
pub fn save_issue(jira: &Jira, loaded: &IssueDetails, summary: Option<&str>, description: Option<&str>) -> anyhow::Result<IssueDetails> {
    let now = jira.issue_details(&loaded.key)?;
    if now.updated != loaded.updated {
        anyhow::bail!("{} changed in Jira since you opened it; ⟳ Reload loads the new version (your unsaved text is discarded)", loaded.key);
    }
    jira.update_issue(&loaded.key, summary, description)?;
    jira.issue_details(&loaded.key)
}

/// A history record as the list shows it: the title it was created or last saved with, and its
/// creation time as the status.
pub fn list_entry(r: &TicketRecord) -> Issue {
    let created = chrono::DateTime::from_timestamp(r.created, 0)
        .map(|t| t.with_timezone(&chrono::Local).format("created %Y-%m-%d %H:%M").to_string())
        .unwrap_or_default();
    Issue { key: r.key.clone(), summary: r.title.clone(), status: created }
}

/// The tickets matching the project (`None`: all) and every word of `query` in the key or the
/// summary, ignoring case, in list order.
pub fn filter_issues<'a>(list: &'a [Issue], project: Option<&str>, query: &str) -> Vec<&'a Issue> {
    let words: Vec<String> = query.split_whitespace().map(str::to_lowercase).collect();
    list.iter()
        .filter(|i| project.is_none_or(|p| project_of(&i.key).eq_ignore_ascii_case(p)))
        .filter(|i| {
            let hay = format!("{} {}", i.key, i.summary).to_lowercase();
            words.iter().all(|w| hay.contains(w))
        })
        .collect()
}

enum Regen {
    Stage(Stage),
    Done(anyhow::Result<TicketDraft>),
}

/// One ticket open for editing.
pub struct Editor {
    /// The ticket as Jira had it when loaded or last saved.
    pub loaded: IssueDetails,
    pub title: String,
    pub description: String,
    pub error: Option<String>,
    /// A short success note ("saved", "regenerated").
    pub notice: Option<String>,
    /// What the ticket was created from, and the language it was written in.
    pub sources: Vec<WorkItem>,
    pub language: String,
    /// The author's instructions for Regenerate; kept after it, to refine and run again.
    pub instructions: String,
    regenerating: Option<(Receiver<Regen>, Option<Stage>)>,
    saving: Option<Receiver<anyhow::Result<IssueDetails>>>,
}

impl Editor {
    /// The editor for `loaded`, regenerated from `sources` in `language`.
    pub fn new(loaded: IssueDetails, sources: Vec<WorkItem>, language: String) -> Self {
        Self {
            title: loaded.summary.clone(),
            description: loaded.description.clone(),
            loaded,
            error: None,
            notice: None,
            sources,
            language,
            instructions: String::new(),
            regenerating: None,
            saving: None,
        }
    }

    pub fn busy(&self) -> bool {
        self.regenerating.is_some() || self.saving.is_some()
    }

    /// The fields Save sends, as (summary, description): each only when it differs from Jira's
    /// ignoring surrounding whitespace, trimmed.
    pub fn changes(&self) -> (Option<String>, Option<String>) {
        let changed = |now: &str, was: &str| (now.trim() != was.trim()).then(|| now.trim().to_owned());
        (changed(&self.title, &self.loaded.summary), changed(&self.description, &self.loaded.description))
    }

    pub fn is_dirty(&self) -> bool {
        self.changes() != (None, None)
    }

    /// Save is possible: something changed and the title is not blank.
    pub fn can_save(&self) -> bool {
        self.is_dirty() && !self.title.trim().is_empty() && !self.busy()
    }

    pub fn revert(&mut self) {
        self.title = self.loaded.summary.clone();
        self.description = self.loaded.description.clone();
        self.error = None;
        self.notice = None;
    }

    /// A regenerated ticket fills the fields (not saved); an error is kept for display and the
    /// fields stay as they were.
    pub fn apply_redraft(&mut self, res: anyhow::Result<TicketDraft>) {
        match res {
            Ok(d) => {
                self.title = d.title;
                self.description = d.description;
                self.error = None;
                self.notice = Some("regenerated — check it, edit it if needed, then Save changes".into());
            }
            Err(e) => {
                self.error = Some(format!("{e:#}"));
                self.notice = None;
            }
        }
    }

    /// The outcome of Save: Jira's new state becomes the baseline (the fields keep what was typed,
    /// so nothing typed during the save is lost) and the ticket is returned for the main window.
    pub fn apply_saved(&mut self, res: anyhow::Result<IssueDetails>) -> Option<Issue> {
        match res {
            Ok(d) => {
                let issue = Issue { key: d.key.clone(), summary: d.summary.clone(), status: d.status.clone() };
                self.loaded = d;
                self.error = None;
                self.notice = Some("saved to Jira".into());
                Some(issue)
            }
            Err(e) => {
                self.error = Some(format!("{e:#}"));
                self.notice = None;
                None
            }
        }
    }

    /// What Regenerate sends: the ticket as the fields hold it now, the language (the stored one,
    /// else `default_language`), the stored sources (diffs dropped when `send_code` is off) and
    /// the author's instructions.
    pub fn regen_request(&self, default_language: &str, send_code: bool) -> (CurrentTicket, String, Vec<WorkItem>, String) {
        let current = CurrentTicket { key: self.loaded.key.clone(), title: self.title.clone(), description: self.description.clone() };
        let language = if self.language.trim().is_empty() { default_language.to_owned() } else { self.language.clone() };
        (current, language, regen_items(&self.sources, send_code), self.instructions.clone())
    }

    /// Rewrites the fields with the LLM from what they hold now and the stored sources (their
    /// diffs dropped when `send_code` is off).
    // What exactly is sent is `regen_request`.
    fn regenerate(&mut self, cfg: &Config) {
        let creds = match llm::credentials(&cfg.tickets, |k| std::env::var(k).ok()) {
            Ok(c) => c,
            Err(e) => {
                self.error = Some(format!("{e:#}"));
                return;
            }
        };
        self.error = None;
        self.notice = None;
        let (current, language, items, instructions) = self.regen_request(&cfg.tickets.language, cfg.tickets.send_code);
        log::info!("regenerating {} with {} from {} stored items", current.key, creds.model, items.len());
        let (tx, rx) = channel();
        std::thread::spawn(move || {
            let progress_tx = tx.clone();
            let progress = move |s: Stage| {
                log::info!("regenerating step {}/4: {}", s.number(), s.label());
                let _ = progress_tx.send(Regen::Stage(s));
            };
            let res = drafting::redraft_ticket_with(&Llm::new(creds), project_of(&current.key), &language, &current, &items, &instructions, &progress);
            if let Err(e) = &res {
                log::error!("regenerating {}: {e:#}", current.key);
            }
            let _ = tx.send(Regen::Done(res));
        });
        self.regenerating = Some((rx, None));
    }

    /// Saves the changed fields on a thread (`save_issue`).
    fn save(&mut self, creds: &JiraCredentials) {
        let (summary, description) = self.changes();
        if summary.is_none() && description.is_none() {
            return;
        }
        self.error = None;
        self.notice = None;
        let (creds, loaded) = (creds.clone(), self.loaded.clone());
        let (tx, rx) = channel();
        std::thread::spawn(move || {
            let jira = Jira::new(&creds.url, &creds.token);
            let res = save_issue(&jira, &loaded, summary.as_deref(), description.as_deref());
            if let Err(e) = &res {
                log::error!("saving {}: {e:#}", loaded.key);
            }
            let _ = tx.send(res);
        });
        self.saving = Some(rx);
    }

    fn poll(&mut self) -> Option<Issue> {
        if let Some((rx, stage)) = &mut self.regenerating {
            loop {
                match rx.try_recv() {
                    Ok(Regen::Stage(s)) => *stage = Some(s),
                    Ok(Regen::Done(res)) => {
                        self.regenerating = None;
                        self.apply_redraft(res);
                        break;
                    }
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        self.regenerating = None;
                        self.error = Some("regenerating stopped unexpectedly".into());
                        break;
                    }
                }
            }
        }
        if let Some(rx) = &self.saving {
            match rx.try_recv() {
                Ok(res) => {
                    self.saving = None;
                    return self.apply_saved(res);
                }
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => {
                    self.saving = None;
                    self.error = Some("saving stopped unexpectedly".into());
                }
            }
        }
        None
    }
}

/// What the main window must do after a frame of the browser.
pub enum BrowserOutcome {
    /// A ticket was saved: show its new summary wherever it is listed.
    Updated(Issue),
}

pub struct IssueBrowser {
    /// Project filter; `None` shows all.
    pub project: Option<String>,
    pub query: String,
    /// `None` when the history file could not be opened (the reason is in `list_error`).
    history: Option<Arc<History>>,
    pub records: Vec<TicketRecord>,
    pub list: Vec<Issue>,
    pub list_error: Option<String>,
    pub editor: Option<Editor>,
    /// A ticket being loaded into the editor.
    loading: Option<(String, Receiver<anyhow::Result<IssueDetails>>)>,
    /// A ticket the user clicked while the editor had unsaved changes, awaiting "Discard".
    pub pending_open: Option<String>,
}

impl IssueBrowser {
    /// A browser over `history` (`Err`: why there is none), listing it right away.
    pub fn new(history: Result<Arc<History>, String>) -> Self {
        let (history, list_error) = match history {
            Ok(h) => (Some(h), None),
            Err(e) => (None, Some(format!("ticket history unavailable: {e}"))),
        };
        let mut b = Self { project: None, query: String::new(), history, records: Vec::new(), list: Vec::new(), list_error, editor: None, loading: None, pending_open: None };
        b.refresh();
        b
    }

    pub fn busy(&self) -> bool {
        self.loading.is_some() || self.editor.as_ref().is_some_and(Editor::busy)
    }

    /// Something running that must not be dropped by closing the window: a save or a regeneration.
    pub fn editor_busy(&self) -> bool {
        self.editor.as_ref().is_some_and(Editor::busy)
    }

    /// Rereads the history: records of the last `KEEP_DAYS` days, newest first.
    pub fn refresh(&mut self) {
        let Some(h) = &self.history else { return };
        match h.recent(chrono::Local::now().timestamp()) {
            Ok(r) => {
                self.list = r.iter().map(list_entry).collect();
                self.records = r;
                self.list_error = None;
            }
            Err(e) => self.list_error = Some(format!("reading the ticket history: {e:#}")),
        }
    }

    /// Asks to open `key`: straight away, unless the editor holds unsaved changes to another
    /// ticket, which first need "Discard" (`pending_open`). Returns whether it may load now.
    pub fn request_open(&mut self, key: &str) -> bool {
        match &self.editor {
            Some(e) if e.busy() => false,
            Some(e) if e.is_dirty() && e.loaded.key != key => {
                self.pending_open = Some(key.to_owned());
                false
            }
            // Reloading the open ticket discards its edits too, so it asks the same way.
            Some(e) if e.loaded.key == key && e.is_dirty() => {
                self.pending_open = Some(key.to_owned());
                false
            }
            _ => {
                self.pending_open = None;
                true
            }
        }
    }

    fn load(&mut self, creds: &JiraCredentials, key: &str) {
        let (creds, k) = (creds.clone(), key.to_owned());
        let (tx, rx) = channel();
        std::thread::spawn(move || {
            let _ = tx.send(Jira::new(&creds.url, &creds.token).issue_details(&k));
        });
        self.loading = Some((key.to_owned(), rx));
    }

    /// A saved ticket's new title in the list and in its history record (regenerating it later
    /// starts from the saved text).
    pub fn apply_updated(&mut self, issue: &Issue, description: &str) {
        for i in self.list.iter_mut().filter(|i| i.key == issue.key) {
            i.summary = issue.summary.clone();
        }
        for r in self.records.iter_mut().filter(|r| r.key == issue.key) {
            r.title = issue.summary.clone();
            r.description = description.to_owned();
        }
        if let Some(h) = &self.history
            && let Err(e) = h.update_text(&issue.key, &issue.summary, description)
        {
            log::warn!("ticket history: updating {}: {e:#}", issue.key);
        }
    }

    fn poll(&mut self) -> Vec<BrowserOutcome> {
        let mut out = Vec::new();
        if let Some((key, rx)) = &self.loading {
            match rx.try_recv() {
                Ok(Ok(d)) => {
                    let record = self.records.iter().find(|r| r.key == d.key);
                    let (sources, language) = record.map(|r| (r.sources.clone(), r.language.clone())).unwrap_or_default();
                    self.editor = Some(Editor::new(d, sources, language));
                    self.loading = None;
                }
                Ok(Err(e)) => {
                    let msg = format!("loading {key}: {e:#}");
                    self.list_error = Some(msg);
                    self.loading = None;
                }
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => self.loading = None,
            }
        }
        if let Some(issue) = self.editor.as_mut().and_then(Editor::poll) {
            let description = self.editor.as_ref().map(|e| e.loaded.description.clone()).unwrap_or_default();
            self.apply_updated(&issue, &description);
            out.push(BrowserOutcome::Updated(issue));
        }
        out
    }

    /// Draws the window. Returns false once the user closed it (never while a save or
    /// regeneration runs).
    pub fn show(&mut self, ctx: &egui::Context, cfg: &Config, creds: &JiraCredentials, projects: &[(String, String)]) -> (bool, Vec<BrowserOutcome>) {
        let outcomes = self.poll();
        if self.busy() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
        let mut open = true;
        egui::Window::new("My Jira tickets")
            .id(egui::Id::new("my-tickets"))
            .open(&mut open)
            .default_size([980.0, 640.0])
            .collapsible(false)
            .resizable(true)
            .show(ctx, |ui| self.body(ui, cfg, creds, projects));
        (open || self.editor_busy(), outcomes)
    }

    fn body(&mut self, ui: &mut egui::Ui, cfg: &Config, creds: &JiraCredentials, projects: &[(String, String)]) {
        ui.horizontal_wrapped(|ui| {
            ui.selectable_value(&mut self.project, None, "All");
            for (k, l) in projects {
                ui.selectable_value(&mut self.project, Some(k.clone()), l);
            }
            ui.separator();
            ui.add(egui::TextEdit::singleline(&mut self.query).hint_text("search key or title").desired_width(200.0));
            if ui.button("⟳ Refresh").on_hover_text("read the list again (tickets created since appear)").clicked() {
                self.refresh();
            }
        });
        if let Some(e) = &self.list_error {
            ui.colored_label(egui::Color32::from_rgb(200, 60, 50), e);
        }
        ui.separator();

        let mut clicked: Option<String> = None;
        let selected = self.editor.as_ref().map(|e| e.loaded.key.clone());
        ui.horizontal_top(|ui| {
            ui.vertical(|ui| {
                ui.set_width(330.0);
                let shown = filter_issues(&self.list, self.project.as_deref(), &self.query);
                ui.weak(format!("{} of {} tickets created here in the last {KEEP_DAYS} days", shown.len(), self.list.len()))
                    .on_hover_text(self.history.as_ref().map_or_else(|| "no ticket history".to_owned(), |h| format!("stored in {}", h.path().display())));
                egui::ScrollArea::vertical().id_salt("my-tickets-list").max_height(520.0).auto_shrink([false, false]).show(ui, |ui| {
                    for i in shown {
                        let text = egui::RichText::new(format!("{}  {}", i.key, i.summary)).size(EVIDENCE_TEXT_SIZE);
                        let r = ui.selectable_label(selected.as_deref() == Some(i.key.as_str()), text).on_hover_text(&i.status);
                        if r.clicked() {
                            clicked = Some(i.key.clone());
                        }
                    }
                });
            });
            ui.separator();
            ui.vertical(|ui| self.editor_ui(ui, cfg, creds));
        });
        if let Some(k) = clicked
            && self.request_open(&k)
        {
            self.load(creds, &k);
        }
    }

    fn editor_ui(&mut self, ui: &mut egui::Ui, cfg: &Config, creds: &JiraCredentials) {
        if let Some((key, _)) = &self.loading {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label(format!("loading {key}…"));
            });
            return;
        }
        if let Some(next) = self.pending_open.clone() {
            let from = self.editor.as_ref().map(|e| e.loaded.key.clone()).unwrap_or_default();
            ui.horizontal_wrapped(|ui| {
                ui.colored_label(egui::Color32::from_rgb(190, 130, 20), format!("{from} has unsaved changes. Discard them and open {next}?"));
                if ui.button("Discard").clicked() {
                    self.pending_open = None;
                    self.load(creds, &next);
                }
                if ui.button("Keep editing").clicked() {
                    self.pending_open = None;
                }
            });
            ui.separator();
        }
        let Some(ed) = &mut self.editor else {
            ui.weak("Pick a ticket on the left to edit or regenerate it. Only tickets created with ➕ New ticket in the last week are listed: they keep what they were drafted from.");
            return;
        };
        let editable = !ed.busy();
        let mut reload: Option<String> = None;
        ui.horizontal(|ui| {
            ui.hyperlink_to(egui::RichText::new(&ed.loaded.key).strong().size(EVIDENCE_TEXT_SIZE), format!("{}/browse/{}", creds.url, ed.loaded.key));
            ui.weak(&ed.loaded.status);
            if ed.is_dirty() {
                ui.colored_label(egui::Color32::from_rgb(190, 130, 20), "unsaved changes");
            }
        });
        ui.label("Title");
        ui.add_enabled(editable, egui::TextEdit::singleline(&mut ed.title).char_limit(MAX_TITLE_CHARS).desired_width(f32::INFINITY));
        ui.label("Description (Jira wiki markup)");
        egui::ScrollArea::vertical().id_salt("my-ticket-description").max_height(380.0).show(ui, |ui| {
            ui.add_enabled(editable, egui::TextEdit::multiline(&mut ed.description).desired_rows(16).desired_width(f32::INFINITY).code_editor());
        });
        ui.label("Instructions for Regenerate (optional)");
        ui.add_enabled(
            editable,
            egui::TextEdit::multiline(&mut ed.instructions)
                .hint_text("e.g. add a test case for an expired token · shorter description · mention that the admin panel is affected")
                .desired_rows(2)
                .desired_width(f32::INFINITY),
        );
        ui.add_space(4.0);
        ui.horizontal(|ui| {
            let regen = ui
                .add_enabled(editable, egui::Button::new("✨ Regenerate"))
                .on_hover_text(format!(
                    "{} rewrites the title and description from what is in the fields now and the {} lines {} was created from{}, \
                     in four steps (analyst, writer, tester, reviewer). Nothing is saved until you click Save changes.",
                    cfg.tickets.llm_model,
                    ed.sources.len(),
                    ed.loaded.key,
                    if cfg.tickets.send_code { " with their diffs" } else { "" }
                ));
            if regen.clicked() {
                ed.regenerate(cfg);
            }
            if ui.add_enabled(editable && ed.is_dirty(), egui::Button::new("↺ Revert")).on_hover_text("back to the version loaded from Jira").clicked() {
                ed.revert();
            }
            if ui.add_enabled(editable, egui::Button::new("⟳ Reload")).on_hover_text("load the ticket from Jira again (asks first when there are unsaved changes)").clicked() {
                reload = Some(ed.loaded.key.clone());
            }
            let save = ui
                .add_enabled(ed.can_save(), egui::Button::new(egui::RichText::new("💾 Save changes").strong()))
                .on_hover_text("write the changed title and description to Jira")
                .on_disabled_hover_text("nothing changed, the title is empty, or a step is still running");
            if save.clicked() {
                ed.save(creds);
            }
            if let Some((_, stage)) = &ed.regenerating {
                ui.spinner();
                ui.label(match stage {
                    Some(s) => format!("{}/4 {}…", s.number(), s.label()),
                    None => "starting…".to_owned(),
                });
            }
            if ed.saving.is_some() {
                ui.spinner();
                ui.label("saving…");
            }
        });
        if let Some(e) = &ed.error {
            ui.colored_label(egui::Color32::from_rgb(200, 60, 50), e);
        }
        if let Some(n) = &ed.notice {
            ui.colored_label(egui::Color32::from_rgb(40, 140, 60), n);
        }
        if let Some(k) = reload
            && self.request_open(&k)
        {
            self.load(creds, &k);
        }
    }
}
